// #511 LIFE plane (life.checkout_attempt.stale): expired-but-not-terminal
// checkout attempts for a scope. Detection (read-only) for the Convergence Engine.
func (q *Queries) ListStaleCheckoutAttempts(ctx context.Context, arg ListStaleCheckoutAttemptsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listStaleCheckoutAttempts, arg.MerchantID, arg.CustomerID, arg.Now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

